import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import API from '../api';

export default function Clients() {
  const [clients, setClients] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    API.get('/clients').then((r) => setClients(r.data)).finally(() => setLoading(false));
  }, []);

  if (loading) return <Loader />;

  return (
    <div style={page}>
      <h1 style={h1}>Our Clients</h1>
      <p style={sub}>Verified licensed businesses we promote</p>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(320px, 1fr))', gap: 24, marginTop: 40 }}>
        {clients.map((c) => (
          <Link key={c.id} to={`/clients/${c.id}`} style={{ textDecoration: 'none' }}>
            <div style={card}>
              <div style={{ display: 'flex', alignItems: 'center', gap: 14, marginBottom: 14 }}>
                <div style={{ width: 56, height: 56, background: 'linear-gradient(135deg,#f97316,#fb923c)', borderRadius: 14, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 26 }}>
                  {c.icon}
                </div>
                <div>
                  <div style={{ fontWeight: 700, fontSize: 16 }}>{c.name}</div>
                  <div style={{ color: '#a3a3a3', fontSize: 13 }}>{c.category}</div>
                </div>
              </div>
              <p style={{ color: '#a3a3a3', fontSize: 14, lineHeight: 1.6, marginBottom: 16 }}>{c.description}</p>
              <div style={{ display: 'flex', gap: 8 }}>
                <span style={verifiedBadge}>✓ Verified</span>
              </div>
              <div style={{ display: 'flex', justifyContent: 'space-around', marginTop: 16, paddingTop: 16, borderTop: '1px solid #262626' }}>
                {[['Followers', c.followers], ['Growth', c.growth], ['Engagement', c.engagement]].map(([l, v]) => (
                  <div key={l} style={{ textAlign: 'center' }}>
                    <div style={{ color: '#f97316', fontWeight: 700, fontSize: 16 }}>{v}</div>
                    <div style={{ color: '#666', fontSize: 12 }}>{l}</div>
                  </div>
                ))}
              </div>
            </div>
          </Link>
        ))}
      </div>
      {clients.length === 0 && <p style={{ color: '#a3a3a3', textAlign: 'center', marginTop: 60 }}>No clients yet.</p>}
    </div>
  );
}

const page = { maxWidth: 1200, margin: '0 auto', padding: '60px 24px' };
const h1 = { fontSize: 40, fontWeight: 900, marginBottom: 8 };
const sub = { color: '#a3a3a3', fontSize: 16 };
const card = { background: '#171717', border: '1px solid #262626', borderRadius: 20, padding: 24, transition: 'border-color 0.2s', cursor: 'pointer' };
const verifiedBadge = { background: '#22c55e15', border: '1px solid #22c55e40', color: '#22c55e', padding: '4px 12px', borderRadius: 20, fontSize: 12, fontWeight: 600 };
const Loader = () => <div style={{ textAlign: 'center', padding: 80, color: '#a3a3a3' }}>Loading...</div>;
